const D = { energy:.5, density:.5, scale:1, speed:1, alpha:.85, hue:22, x:.92, y:1.02, style:'char', act:'creep', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width, Hh=height, u=Math.min(W,Hh), diag=Math.hypot(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'creep';
const isCin=st==='cinder', isNit=st==='nitrate', isCon=st==='contour';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1);
const sp=P.speed, sc=clp(P.scale,0.25,2.2);
const ix=P.x*W, iy=P.y*Hh;

// ---- cached char sheet: mottled warm-black with curl highlights (texture, never flat fill) ----
const key=W+'x'+Hh+'|'+P.seed+'|'+st+'|'+md(Math.round(H),360);
if(!isCon&&(!S.ch||S.key!==key)){
  const bw=Math.max(280,Math.min(460,Math.round(W*0.3))), bh=Math.max(160,Math.round(bw*Hh/W));
  if(!S.ch||S.bw!==bw||S.bh!==bh){ S.ch=createGraphics(bw,bh); S.bw=bw; S.bh=bh; }
  const g=S.ch, uu=Math.min(bw,bh);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  let ctr=0; const rnd=()=>fr(++ctr*1.31+7);
  if(!isCin){ g.fill(md(H-6,360), isNit?34:16, isNit?9:5, isNit?92:96); g.rect(0,0,bw,bh); }
  // soot mottle
  for(let i=0;i<5200;i++){
    const x=rnd()*bw, y=rnd()*bh, r=uu*lrp(0.0012,0.012,rnd()*rnd());
    const up=rnd();
    g.fill(md(H+(up>0.72?18:-10),360), isNit?lrp(40,10,up):lrp(26,4,up), up>0.9?lrp(10,26,rnd()):lrp(1,7,up), isCin?26:lrp(24,70,rnd()));
    g.circle(x,y,r*2);
  }
  // curled paper lifting off the char — the tell that this is burnt sheet, not just black
  g.noFill();
  for(let i=0;i<44;i++){
    const x=rnd()*bw, y=rnd()*bh, r=uu*lrp(0.02,0.09,rnd()), a0=rnd()*6.283, sw=rnd()*2.2+0.9;
    g.stroke(md(H+16,360), isNit?30:22, lrp(14,34,rnd()), lrp(14,42,rnd())); g.strokeWeight(sw);
    g.arc(x,y,r*2,r*lrp(0.5,1.6,rnd()),a0,a0+lrp(1.1,2.7,rnd()));
  }
  if(isNit){ // nitrate blisters: bubbling melt-through holes in the emulsion
    g.noStroke();
    for(let i=0;i<170;i++){
      const x=rnd()*bw, y=rnd()*bh, r=uu*lrp(0.004,0.030,rnd()*rnd());
      g.fill(md(H+26,360),18,lrp(52,96,rnd()),lrp(30,80,rnd())); g.circle(x,y,r*2);
      g.fill(md(H-8,360),40,4,86); g.circle(x-r*0.2,y-r*0.2,r*1.1);
    }
  }
  S.key=key;
}

// ---- the burn front: a licking, star-shaped isotherm around the ignition ----
let envR=1, envE=1;
if(act==='consume'){ envR=0.30+1.45*frc(K.t/(74/Math.max(0.1,sp))); }       // eats the frame over ~74s, then a fresh sheet
else if(act==='fan'){ envR=0.80+0.55*K.intensity; envE=0.75+0.85*K.intensity; }
const breathe=0.55*Math.sin(K.t*0.083*sp)+0.28*Math.sin(K.t*0.197*sp+1.3)+0.17*Math.sin(K.t*0.041*sp+0.7);
const R0=diag*(0.05+0.55*en)*sc*envR*(0.88+0.12*breathe+0.05*A.bass);
const q1=fr(21)*6.283, q2=fr(22)*6.283;
const rimAt=(th,tt)=>{
  const lick=0.50*Math.sin(th*7+tt*0.31*sp+q1)+0.28*Math.sin(th*13-tt*0.53*sp+q2)+0.16*Math.sin(th*23+tt*0.87*sp);
  return R0*(0.74+0.32*lick)*(1+0.06*Math.sin(th*3+tt*0.13*sp));
};
const NA=128, pts=[];
for(let i=0;i<NA;i++){ const th=i/NA*6.283, r=rimAt(th,K.t); pts.push([ix+Math.cos(th)*r, iy+Math.sin(th)*r, th, r]); }

// ---- contour style: pure thermal isotherm schematic, no char at all ----
if(isCon){
  noFill();
  for(let b=0;b<7;b++){
    const f=b/6, kk=lrp(1.30,0.34,f);
    stroke(md(H+f*185,360), lrp(88,54,f), lrp(100,58,f), clp((72-b*7)*al*(0.35+0.9*en),0,92));
    strokeWeight(Math.max(0.5,u*(b===0?0.0032:0.0012)*sc));
    beginShape();
    for(let i=0;i<NA;i++){ const th=pts[i][2], r=pts[i][3]*kk; vertex(ix+Math.cos(th)*r, iy+Math.sin(th)*r); }
    endShape(CLOSE);
  }
} else {
  // scorch halo just beyond the front
  noFill();
  for(let b=0;b<3;b++){
    stroke(md(H-4,360), lrp(52,30,b/2), lrp(30,14,b/2), clp((16-b*4)*al,0,26));
    strokeWeight(u*lrp(0.010,0.034,b/2)*sc);
    beginShape();
    for(let i=0;i<NA;i++){ const th=pts[i][2], r=pts[i][3]*(1.015+b*0.030); vertex(ix+Math.cos(th)*r, iy+Math.sin(th)*r); }
    endShape(CLOSE);
  }
  // char sheet, clipped to the burnt region
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.moveTo(pts[0][0],pts[0][1]);
  for(let i=1;i<NA;i++) drawingContext.lineTo(pts[i][0],pts[i][1]);
  drawingContext.closePath();
  drawingContext.clip();
  if(isCin) blendMode(ADD);
  tint(0,0,100,al*100); image(S.ch,0,0,W,Hh); noTint();
  blendMode(BLEND);
  drawingContext.restore();
}

// ---- ember rim: three passes of SEGMENTS (p5 cannot vary stroke inside beginShape),
// brightness shimmering ALONG the line — never a frame flash ----
if(!isCon){
  const gl=(0.42+0.72*en)*envE*al;
  noFill();
  for(let pass=0;pass<3;pass++){
    strokeWeight(Math.max(0.6,u*[0.026,0.010,0.0035][pass]*sc*(0.7+0.5*en)));
    for(let i=0;i<NA;i++){
      const a=pts[i], b=pts[(i+1)%NA], th=a[2];
      // localized flicker travelling along the rim, small amplitude
      const fl=0.62+0.38*(0.5+0.5*Math.sin(th*17+K.t*2.3*sp+q1))*(0.5+0.5*Math.sin(th*5-K.t*1.1*sp));
      const sat=isNit?lrp(24,4,fl):lrp(96,58,fl);
      const br=[lrp(56,90,fl),lrp(84,100,fl),100][pass];
      const aa=clp([26,52,82][pass]*gl*(0.55+0.6*fl),0,94);
      if(aa<1.5) continue;
      stroke(md(H+[-6,6,22][pass]+fl*10,360), sat, br, aa);
      line(a[0],a[1],b[0],b[1]);
    }
  }
}

// ---- ash lifting off the rim: ember-hot at birth, grey and tumbling as it climbs ----
{
  const nA=Math.round(lrp(26,110,dn));
  noStroke();
  for(let i=0;i<nA;i++){
    const j=i*23;
    const th=fr(j+1)*6.283;
    const rate=(0.10+fr(j+2)*0.20)*sp*(0.5+0.8*en);
    const ph=frc(fr(j+3)+K.t*rate);
    const b=rimAt(th,K.t);
    const bx=ix+Math.cos(th)*b, by=iy+Math.sin(th)*b;
    const rise=u*lrp(0.10,0.44,fr(j+4))*sc*(0.4+1.1*en);
    const ax2=bx + Math.sin(K.t*(0.6+fr(j+5)*1.7)*sp+fr(j+6)*6.283)*u*0.05*ph*(0.4+en) + (fr(j+7)-0.5)*u*0.08*ph;
    const ay2=by - rise*Math.pow(ph,0.78);
    if(ay2<-u*0.06||ax2<-u*0.06||ax2>W+u*0.06) continue;
    const cool=Math.pow(ph,0.55);
    const rad=u*lrp(0.0016,0.0062,fr(j+8))*sc;
    const flip=Math.abs(Math.cos(K.t*(1.1+fr(j+9)*2.6)*sp+fr(j+10)*6.283)); // edge-on tumble
    const aa=clp((1-ph)*(1-ph*0.45)*96*al*(0.4+0.8*en),0,92);
    if(aa<2) continue;
    push(); translate(ax2,ay2); rotate(K.t*(0.5+fr(j+11)*1.6)*sp+fr(j+12)*6.283);
    if(cool<0.34){ fill(md(H+lrp(18,0,cool/0.34),360), lrp(30,96,cool/0.34), 100, aa); }
    else { fill(md(H+8,360), lrp(30,6,(cool-0.34)/0.66), lrp(58,30,(cool-0.34)/0.66), aa*0.86); }
    ellipse(0,0, rad*2*(0.25+0.75*flip), rad*2);
    if(cool<0.2){ fill(md(H+26,360),18,100,aa*0.7); ellipse(0,0,rad*1.1*(0.25+0.75*flip),rad*1.1); }
    pop();
  }
}

